#!/usr/bin/env python3
"""Deterministic data generator: Qt preset TSV bytes -> shared core C++ constants.

Run from anywhere:
  python src/config/generate_roman_table_presets_cc.py --repo <repo root>
Then compile/test. Do not edit the .cc output by hand.
"""
import argparse
import hashlib
from pathlib import Path

PRESETS = [
    ('simplified_azik', 'SimplifiedAzik'),
    ('shingetsu', 'Shingetsu'),
    ('seoto', 'Seoto'),
    ('seoto_plus', 'SeotoPlus'),
]

HEADER = '''// Generated by src/config/generate_roman_table_presets_cc.py.
// Do not edit. Update the .tsv in gui/config_dialog/roman_table_presets,
// then rerun the generator. Exact raw TSV bytes are embedded here.
#include "config/roman_table_presets.h"

#include <string>

#include "base/hash.h"

namespace mozc {
namespace config {
namespace {
'''

FOOTER = '''}  // namespace

absl::string_view GetRomanTablePreset(absl::string_view id) {
  if (id == "simplified_azik") return absl::string_view(kSimplifiedAzik);
  if (id == "shingetsu") return absl::string_view(kShingetsu);
  if (id == "seoto") return absl::string_view(kSeoto);
  if (id == "seoto_plus") return absl::string_view(kSeotoPlus);
  return {};
}

absl::string_view ResolveRomanTablePreset(const Config& config,
                                         absl::string_view id) {
  const absl::string_view builtin = GetRomanTablePreset(id);
  if (!builtin.empty()) return builtin;
  if (!id.starts_with("user:")) return {};
  const absl::string_view local_id = id.substr(5);
  for (const auto &preset : config.user_roman_table_presets()) {
    if (absl::string_view(preset.id()) == local_id && !preset.table().empty() &&
        preset.table().size() <= 64 * 1024) return preset.table();
  }
  return {};
}

void NormalizeRomanTablePreset(Config* config) {
  if (config->roman_table_preset_id().empty()) {
    config->clear_roman_table_preset_snapshot_hash();
    return;
  }
  const absl::string_view latest =
      ResolveRomanTablePreset(*config, config->roman_table_preset_id());
  const bool matches_snapshot =
      config->has_roman_table_preset_snapshot_hash() &&
      config->roman_table_preset_snapshot_hash() ==
          CityFingerprint(config->custom_roman_table());
  if (latest.empty() || !matches_snapshot) {
    // An unknown/removed preset or externally edited table becomes custom.
    // Never overwrite data that has been changed outside the editor.
    config->clear_roman_table_preset_id();
    config->clear_roman_table_preset_snapshot_hash();
    return;
  }
  if (absl::string_view(config->custom_roman_table()) != latest) {
    config->set_custom_roman_table(std::string(latest.data(), latest.size()));
  }
  config->set_roman_table_preset_snapshot_hash(
      CityFingerprint(config->custom_roman_table()));
}

}  // namespace config
}  // namespace mozc
'''


def render(repo: Path) -> bytes:
    pieces = [HEADER]
    preset_dir = repo / 'src/gui/config_dialog/roman_table_presets'
    for filename, symbol in PRESETS:
        b = (preset_dir / (filename + '.tsv')).read_bytes()
        if not b or b'\x00' in b or len(b) > 128 * 1024:
            raise ValueError(f'{filename}: invalid preset byte stream')
        b.decode('utf-8')
        pieces.append('// ' + filename + '.tsv: sha256=' + hashlib.sha256(b).hexdigest() + '\n')
        pieces.append('constexpr char k' + symbol + '[] =\n')
        # Hex escapes are encoding-agnostic on Windows, and chunks prevent
        # adjacent hex digit parsing surprises and long compiler source lines.
        for p in range(0, len(b), 24):
            chunk = b[p:p+24]
            pieces.append('    "' + ''.join('\\x%02x' % c for c in chunk) + '"\n')
        pieces.append('    ;\n\n')
    pieces.append(FOOTER)
    return ''.join(pieces).encode('ascii')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--repo', required=True, type=Path)
    ap.add_argument('--check', action='store_true')
    ns = ap.parse_args()
    content = render(ns.repo)
    dest = ns.repo / 'src/config/roman_table_presets.cc'
    if ns.check:
        if not dest.is_file() or dest.read_bytes() != content:
            raise SystemExit('Preset core data diverged: regenerate roman_table_presets.cc')
        print('MOZKEY_ROMAJI_PRESET_CORE_DATA=PASS')
    else:
        dest.write_bytes(content)
        print(f'Generated={dest} Bytes={len(content)}')

if __name__ == '__main__':
    main()
